[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>DeployCloud Blog — Discover the latest in web development</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --bg:#FAFAFA;
  --bg-white:#FFFFFF;
  --fg:#171717;
  --fg-muted:#555555;
  --fg-light:#888888;
  --accent:#0072F5;
  --accent-hover:#0056CC;
  --accent-light:#E8F1FE;
  --border:#E5E7EB;
  --border-light:#F0F0F0;
  --shadow-sm:0 1px 2px rgba(0,0,0,0.04);
  --shadow:0 1px 3px rgba(0,0,0,0.06),0 1px 2px rgba(0,0,0,0.04);
  --shadow-md:0 4px 12px rgba(0,0,0,0.06);
  --shadow-lg:0 8px 30px rgba(0,0,0,0.08);
  --radius:0.5rem;
  --radius-lg:0.75rem;
  --radius-xl:1rem;
  --font:'Inter',system-ui,-apple-system,sans-serif;
  --max-width:1280px;
  --header-h:64px;
}
html{scroll-behavior:smooth}
body{
  font-family:var(--font);
  background:var(--bg);
  color:var(--fg);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
}

/* ── Header ── */
.header{
  position:sticky;top:0;z-index:100;
  background:rgba(255,255,255,0.85);
  backdrop-filter:blur(12px);
  -webkit-backdrop-filter:blur(12px);
  border-bottom:1px solid var(--border);
  height:var(--header-h);
}
.header-inner{
  max-width:var(--max-width);
  margin:0 auto;
  padding:0 2rem;
  height:100%;
  display:flex;
  align-items:center;
  gap:2rem;
}
.logo{
  font-size:1.2rem;
  font-weight:700;
  color:var(--fg);
  text-decoration:none;
  display:flex;
  align-items:center;
  gap:0.5rem;
  letter-spacing:-0.02em;
  white-space:nowrap;
}
.logo svg{flex-shrink:0}
.nav{display:flex;align-items:center;gap:0.25rem;flex:1}
.nav-item{
  position:relative;
  padding:0.5rem 0.75rem;
  font-size:0.875rem;
  font-weight:500;
  color:var(--fg-muted);
  cursor:pointer;
  border-radius:var(--radius);
  transition:color 0.15s,background 0.15s;
  user-select:none;
  white-space:nowrap;
}
.nav-item:hover,.nav-item.active{color:var(--fg);background:var(--bg)}
.nav-chevron{
  display:inline-block;
  width:14px;height:14px;
  margin-left:2px;
  vertical-align:-3px;
  transition:transform 0.2s;
}
.nav-item.open .nav-chevron{transform:rotate(180deg)}
.header-right{
  display:flex;
  align-items:center;
  gap:0.75rem;
  margin-left:auto;
}
.btn{
  display:inline-flex;align-items:center;justify-content:center;
  gap:0.5rem;
  font-family:var(--font);
  font-size:0.875rem;font-weight:500;
  border-radius:var(--radius);
  cursor:pointer;
  transition:all 0.15s;
  border:none;
  text-decoration:none;
  white-space:nowrap;
  padding:0.5rem 1rem;
}
.btn-ghost{background:transparent;color:var(--fg-muted)}
.btn-ghost:hover{color:var(--fg);background:var(--bg)}
.btn-primary{
  background:var(--accent);
  color:#fff;
}
.btn-primary:hover{background:var(--accent-hover)}
.btn-outline{
  background:transparent;
  color:var(--fg);
  border:1px solid var(--border);
}
.btn-outline:hover{border-color:var(--fg-muted)}
.btn-lg{padding:0.75rem 1.5rem;font-size:0.9375rem;border-radius:var(--radius-lg)}

/* ── Mega Menu ── */
.mega-menu{
  position:absolute;top:calc(100% + 0.5rem);left:50%;
  transform:translateX(-50%);
  background:var(--bg-white);
  border:1px solid var(--border);
  border-radius:var(--radius-xl);
  box-shadow:var(--shadow-lg);
  padding:1.5rem;
  opacity:0;visibility:hidden;
  transition:opacity 0.2s,visibility 0.2s,transform 0.2s;
  transform-origin:top center;
  z-index:200;
  min-width:720px;
}
.nav-item.open .mega-menu{
  opacity:1;visibility:visible;
}
.products-menu{min-width:800px}
.mega-inner{display:flex;gap:2rem}
.mega-col{flex:1;min-width:0}
.mega-col-label{
  font-size:0.6875rem;
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:0.06em;
  color:var(--fg-light);
  margin-bottom:0.75rem;
  padding:0 0.5rem;
}
.mega-link{
  display:flex;align-items:flex-start;gap:0.75rem;
  padding:0.5rem;
  border-radius:var(--radius);
  text-decoration:none;
  color:var(--fg);
  transition:background 0.15s;
}
.mega-link:hover{background:var(--accent-light)}
.mega-link-icon{
  width:28px;height:28px;
  border-radius:var(--radius);
  background:var(--bg);
  display:flex;align-items:center;justify-content:center;
  flex-shrink:0;
  color:var(--fg-muted);
  font-size:0.85rem;
}
.mega-link-text{flex:1;min-width:0}
.mega-link-title{font-size:0.8125rem;font-weight:600;line-height:1.3}
.mega-link-desc{font-size:0.75rem;color:var(--fg-light);line-height:1.3;margin-top:0.125rem}

/* ── Resources Dropdown ── */
.dropdown{
  position:absolute;top:calc(100% + 0.5rem);left:0;
  background:var(--bg-white);
  border:1px solid var(--border);
  border-radius:var(--radius-xl);
  box-shadow:var(--shadow-lg);
  padding:1.25rem;
  min-width:560px;
  opacity:0;visibility:hidden;
  transition:opacity 0.2s,visibility 0.2s;
  z-index:200;
}
.nav-item.open .dropdown{opacity:1;visibility:visible}
.dropdown-inner{display:flex;gap:2rem}
.drop-col{flex:1}
.drop-link{
  display:block;
  padding:0.375rem 0.5rem;
  font-size:0.8125rem;
  color:var(--fg);
  text-decoration:none;
  border-radius:var(--radius);
  transition:background 0.15s;
}
.drop-link:hover{background:var(--accent-light)}

/* ── Mobile Menu ── */
.mobile-toggle{
  display:none;
  background:none;border:none;
  cursor:pointer;
  padding:0.25rem;
  color:var(--fg);
}
.mobile-menu{
  display:none;
  position:fixed;
  top:var(--header-h);
  left:0;right:0;bottom:0;
  background:var(--bg-white);
  z-index:99;
  overflow-y:auto;
  padding:1rem;
}
.mobile-menu.open{display:block}
.mobile-section{margin-bottom:1rem}
.mobile-section-title{
  display:flex;align-items:center;justify-content:space-between;
  width:100%;
  padding:0.75rem 0.5rem;
  background:none;border:none;
  font-family:var(--font);
  font-size:0.9375rem;font-weight:600;
  color:var(--fg);
  cursor:pointer;
}
.mobile-section-links{display:none;padding-left:1rem}
.mobile-section-links.open{display:block}
.mobile-section-links a{
  display:block;
  padding:0.5rem;
  font-size:0.875rem;
  color:var(--fg-muted);
  text-decoration:none;
  border-radius:var(--radius);
}
.mobile-section-links a:hover{background:var(--bg)}
.mobile-cta{display:flex;gap:0.5rem;margin-top:1rem;padding-top:1rem;border-top:1px solid var(--border)}

/* ── Page Container ── */
.page{max-width:var(--max-width);margin:0 auto;padding:0 2rem}

/* ── Category Filters ── */
.filters-section{
  padding:2.5rem 0 1.5rem;
  border-bottom:1px solid var(--border-light);
}
.filters-inner{
  display:flex;align-items:center;gap:1rem;
  flex-wrap:wrap;
}
.filter-pills{
  display:flex;gap:0.375rem;
  flex-wrap:wrap;
  flex:1;
}
.filter-pill{
  padding:0.4375rem 0.875rem;
  font-size:0.8125rem;
  font-weight:500;
  font-family:var(--font);
  color:var(--fg-muted);
  background:var(--bg-white);
  border:1px solid var(--border);
  border-radius:100px;
  cursor:pointer;
  transition:all 0.15s;
  white-space:nowrap;
}
.filter-pill:hover{color:var(--fg);border-color:var(--fg-muted)}
.filter-pill.active{
  color:#fff;
  background:var(--accent);
  border-color:var(--accent);
}
.search-wrap{
  position:relative;
  width:260px;
  flex-shrink:0;
}
.search-wrap svg{
  position:absolute;left:0.75rem;top:50%;
  transform:translateY(-50%);
  color:var(--fg-light);
  pointer-events:none;
}
.search-input{
  width:100%;
  padding:0.5rem 0.875rem 0.5rem 2.5rem;
  font-size:0.8125rem;
  font-family:var(--font);
  color:var(--fg);
  background:var(--bg-white);
  border:1px solid var(--border);
  border-radius:100px;
  outline:none;
  transition:border-color 0.15s,box-shadow 0.15s;
}
.search-input::placeholder{color:var(--fg-light)}
.search-input:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(0,114,245,0.1)}

/* ── Section Labels ── */
.section-label{
  font-size:0.6875rem;
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:0.06em;
  color:var(--fg-light);
  margin-bottom:1rem;
}

/* ── Featured Articles ── */
.featured-section{padding:3rem 0 1rem}
.featured-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:1.5rem;
}
.featured-card{
  background:var(--bg-white);
  border:1px solid var(--border);
  border-radius:var(--radius-xl);
  overflow:hidden;
  transition:box-shadow 0.2s,transform 0.2s;
  cursor:pointer;
  display:flex;flex-direction:column;
}
.featured-card:hover{
  box-shadow:var(--shadow-md);
  transform:translateY(-2px);
}
.featured-card-media{
  height:180px;
  background:linear-gradient(135deg,#f0f4ff 0%,#e8f1fe 50%,#dce8fc 100%);
  display:flex;align-items:center;justify-content:center;
  position:relative;
  overflow:hidden;
}
.featured-card-media::after{
  content:'';
  position:absolute;
  right:-30px;bottom:-30px;
  width:120px;height:120px;
  border-radius:50%;
  background:rgba(0,114,245,0.06);
}
.featured-card-media-icon{
  font-size:3rem;
  position:relative;z-index:1;
}
.featured-card-body{
  padding:1.5rem;
  display:flex;flex-direction:column;
  flex:1;
}
.featured-card-meta{
  display:flex;align-items:center;gap:0.5rem;
  margin-bottom:0.75rem;
  font-size:0.75rem;
  color:var(--fg-light);
}
.featured-card-meta .dot{width:3px;height:3px;border-radius:50%;background:var(--fg-light)}
.featured-card-tag{
  font-size:0.6875rem;
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:0.05em;
  color:var(--accent);
}
.featured-card-title{
  font-size:1.25rem;
  font-weight:700;
  line-height:1.3;
  letter-spacing:-0.02em;
  margin-bottom:0.75rem;
  flex:1;
}
.featured-card-excerpt{
  font-size:0.875rem;
  color:var(--fg-muted);
  line-height:1.6;
  margin-bottom:1rem;
  display:-webkit-box;
  -webkit-line-clamp:3;
  -webkit-box-orient:vertical;
  overflow:hidden;
}
.featured-card-author{
  display:flex;align-items:center;gap:0.5rem;
  font-size:0.8125rem;font-weight:500;
}
.author-avatar{
  width:28px;height:28px;
  border-radius:50%;
  background:linear-gradient(135deg,#1a1a2e,#16213e);
  color:#fff;
  display:flex;align-items:center;justify-content:center;
  font-size:0.6875rem;font-weight:600;
  flex-shrink:0;
}

/* Stats ribbon inside first featured card */
.featured-stats-ribbon{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:0.75rem;
  padding:1rem 1.5rem;
  background:var(--accent-light);
  border-top:1px solid rgba(0,114,245,0.15);
}
.featured-stat{text-align:center}
.featured-stat-value{
  font-size:1.1rem;
  font-weight:700;
  color:var(--accent);
  letter-spacing:-0.02em;
}
.featured-stat-label{
  font-size:0.6875rem;
  color:var(--fg-muted);
  margin-top:0.125rem;
  line-height:1.3;
}

/* ── Latest News ── */
.latest-section{padding:3rem 0 2rem}
.latest-header{
  display:flex;align-items:center;justify-content:space-between;
  margin-bottom:1.5rem;
}
.latest-title{font-size:1.5rem;font-weight:700;letter-spacing:-0.02em}
.latest-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:1.5rem;
}
.news-card{
  background:var(--bg-white);
  border:1px solid var(--border);
  border-radius:var(--radius-lg);
  padding:1.5rem;
  transition:box-shadow 0.2s,transform 0.2s;
  cursor:pointer;
  display:flex;flex-direction:column;
}
.news-card:hover{
  box-shadow:var(--shadow-md);
  transform:translateY(-2px);
}
.news-card-category{
  font-size:0.6875rem;
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:0.05em;
  color:var(--accent);
  margin-bottom:0.5rem;
}
.news-card-date{
  font-size:0.75rem;
  color:var(--fg-light);
  margin-bottom:0.75rem;
}
.news-card-title{
  font-size:1.0625rem;
  font-weight:600;
  line-height:1.35;
  letter-spacing:-0.01em;
  margin-bottom:0.75rem;
  flex:1;
}
.news-card-excerpt{
  font-size:0.8125rem;
  color:var(--fg-muted);
  line-height:1.55;
  margin-bottom:1rem;
  display:-webkit-box;
  -webkit-line-clamp:2;
  -webkit-box-orient:vertical;
  overflow:hidden;
}
.news-card-author{
  display:flex;align-items:center;gap:0.5rem;
  font-size:0.8125rem;font-weight:500;
}

/* ── Show More ── */
.show-more-wrap{
  text-align:center;
  padding:1rem 0 3rem;
}
.btn-show-more{
  padding:0.625rem 2rem;
  font-size:0.875rem;
  font-weight:500;
  font-family:var(--font);
  color:var(--fg);
  background:var(--bg-white);
  border:1px solid var(--border);
  border-radius:100px;
  cursor:pointer;
  transition:all 0.15s;
}
.btn-show-more:hover{
  border-color:var(--fg-muted);
  box-shadow:var(--shadow-sm);
}

/* ── Empty State ── */
.empty-state{
  text-align:center;
  padding:4rem 2rem;
  display:none;
}
.empty-state.visible{display:block}
.empty-state-icon{
  font-size:2.5rem;
  margin-bottom:1rem;
  opacity:0.5;
}
.empty-state-text{
  font-size:0.9375rem;
  color:var(--fg-muted);
}

/* ── CTA Banner ── */
.cta-section{padding:0 0 4rem}
.cta-banner{
  background:var(--fg);
  color:#fff;
  border-radius:var(--radius-xl);
  padding:3rem;
  display:grid;
  grid-template-columns:1fr auto;
  gap:2rem;
  align-items:center;
}
.cta-headline{
  font-size:1.5rem;
  font-weight:700;
  line-height:1.3;
  letter-spacing:-0.02em;
}
.cta-actions{display:flex;gap:0.75rem;flex-wrap:wrap}
.cta-enterprise{
  margin-top:2rem;
  padding-top:2rem;
  border-top:1px solid rgba(255,255,255,0.15);
  display:flex;align-items:center;justify-content:space-between;
  gap:1.5rem;
  flex-wrap:wrap;
}
.cta-enterprise-text{
  font-size:0.9375rem;
  color:rgba(255,255,255,0.7);
  line-height:1.5;
}
.btn-white{
  background:#fff;
  color:var(--fg);
}
.btn-white:hover{background:#e5e7eb}
.btn-outline-white{
  background:transparent;
  color:#fff;
  border:1px solid rgba(255,255,255,0.3);
}
.btn-outline-white:hover{border-color:rgba(255,255,255,0.6);background:rgba(255,255,255,0.05)}

/* ── Footer ── */
.footer{
  background:var(--bg-white);
  border-top:1px solid var(--border);
  padding:4rem 0 3rem;
}
.footer-inner{max-width:var(--max-width);margin:0 auto;padding:0 2rem}
.footer-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:2rem;
  margin-bottom:3rem;
}
.footer-col{min-width:0}
.footer-col-title{
  font-size:0.75rem;
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:0.05em;
  color:var(--fg);
  margin-bottom:0.75rem;
}
.footer-link{
  display:block;
  padding:0.25rem 0;
  font-size:0.8125rem;
  color:var(--fg-muted);
  text-decoration:none;
  transition:color 0.15s;
}
.footer-link:hover{color:var(--fg)}
.footer-bottom{
  border-top:1px solid var(--border-light);
  padding-top:2rem;
  display:flex;align-items:center;justify-content:space-between;
  gap:1rem;
  flex-wrap:wrap;
}
.footer-status{
  display:flex;align-items:center;gap:0.5rem;
  font-size:0.8125rem;
  color:var(--fg-muted);
}
.status-dot{
  width:8px;height:8px;
  border-radius:50%;
  background:#22c55e;
  flex-shrink:0;
}
.footer-copy{font-size:0.8125rem;color:var(--fg-light)}

/* ── Animations ── */
@keyframes fadeInUp{
  from{opacity:0;transform:translateY(16px)}
  to{opacity:1;transform:translateY(0)}
}
.animate-in{
  animation:fadeInUp 0.4s ease-out both;
}

/* ── Responsive ── */
@media(max-width:1024px){
  .featured-grid{grid-template-columns:repeat(2,1fr)}
  .featured-card:last-child{display:none}
  .latest-grid{grid-template-columns:repeat(2,1fr)}
  .nav-item.hide-md{display:none}
  .footer-grid{grid-template-columns:repeat(3,1fr)}
  .cta-banner{grid-template-columns:1fr}
}

@media(max-width:768px){
  .header-inner{padding:0 1rem}
  .page{padding:0 1rem}
  .footer-inner{padding:0 1rem}
  .nav{display:none}
  .header-right .btn-ghost,.header-right .btn-outline{display:none}
  .mobile-toggle{display:block}
  .featured-grid{grid-template-columns:1fr}
  .featured-card:last-child{display:flex}
  .latest-grid{grid-template-columns:1fr}
  .filters-inner{flex-direction:column;align-items:stretch}
  .search-wrap{width:100%}
  .filter-pills{overflow-x:auto;flex-wrap:nowrap;padding-bottom:0.25rem;scrollbar-width:none}
  .filter-pills::-webkit-scrollbar{display:none}
  .footer-grid{grid-template-columns:repeat(2,1fr)}
  .cta-banner{padding:2rem}
  .cta-headline{font-size:1.25rem}
  .featured-stats-ribbon{grid-template-columns:1fr;gap:0.5rem}
  .featured-card-media{height:140px}
}

@media(max-width:480px){
  .footer-grid{grid-template-columns:1fr 1fr;gap:1.5rem}
  .cta-enterprise{flex-direction:column;align-items:flex-start}
}
</style>
</head>
