    </a>

    <nav class="nav" id="mainNav">
      <!-- Products -->
      <div class="nav-item" data-menu="products">
        Products
        <svg class="nav-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>
        <div class="mega-menu products-menu">
          <div class="mega-inner">
            <div class="mega-col">
              <div class="mega-col-label">AI Cloud</div>
              <a href="#" class="mega-link">
