  showMoreWrap.style.display = hasMore ? '' : 'none';
}

function resetAndRender(){
  visibleCount = POSTS_PER_PAGE;
  renderPosts();
  window.scrollTo({top:document.getElementById('latestGrid').offsetTop-100,behavior:'smooth'});
}

// ═══ FILTER PILLS ═══
document.getElementById('filterPills').addEventListener('click',e=>{
  const pill = e.target.closest('.filter-pill');
  if(!pill)return;
  document.querySelectorAll('.filter-pill').forEach(p=>p.classList.remove('active'));
  pill.classList.add('active');
  activeCategory = pill.dataset.category;
  resetAndRender();
});

// ═══ SEARCH ═══
document.getElementById('searchInput').addEventListener('input',e=>{
  searchQuery = e.target.value.trim();
  resetAndRender();
});

// ═══ SHOW MORE ═══
document.getElementById('showMoreBtn').addEventListener('click',()=>{
  const filtered = getFilteredPosts();
  visibleCount = Math.min(visibleCount+POSTS_PER_PAGE,filtered.length);
  renderPosts();
});

// ═══ DESKTOP NAV DROPDOWNS ═══
let openMenu = null;

document.querySelectorAll('#mainNav .nav-item[data-menu]').forEach(item=>{
  item.addEventListener('click',function(e){
    e.stopPropagation();
    const menuId = this.dataset.menu;
    if(openMenu===menuId){
      this.classList.remove('open');
      openMenu=null;
    }else{
      if(openMenu){
        document.querySelector(`#mainNav .nav-item[data-menu="${openMenu}"]`)?.classList.remove('open');
      }
      this.classList.add('open');
      openMenu=menuId;
    }
  });

  // Hover support
  item.addEventListener('mouseenter',function(){
    if(openMenu&&openMenu!==this.dataset.menu){
      document.querySelector(`#mainNav .nav-item[data-menu="${openMenu}"]`)?.classList.remove('open');
    }
    this.classList.add('open');
    openMenu=this.dataset.menu;
  });
});

document.querySelector('#mainNav')?.addEventListener('mouseleave',function(){
  document.querySelectorAll('#mainNav .nav-item[data-menu]').forEach(i=>i.classList.remove('open'));
  openMenu=null;
});

// Close on outside click
document.addEventListener('click',function(){
  document.querySelectorAll('#mainNav .nav-item[data-menu]').forEach(i=>i.classList.remove('open'));
  openMenu=null;
});

// ═══ MOBILE MENU ═══
const mobileToggle = document.getElementById('mobileToggle');
const mobileMenu = document.getElementById('mobileMenu');

mobileToggle.addEventListener('click',()=>{
  mobileMenu.classList.toggle('open');
});

document.querySelectorAll('[data-mobile-section]').forEach(btn=>{
  btn.addEventListener('click',function(){
    const target = document.getElementById(this.dataset.mobileSection);
    if(target)target.classList.toggle('open');
  });
});

// ═══ INITIAL RENDER ═══
renderPosts();
</script>

